package ecommerce_payment_service.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.Optional;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;

/**
 * File-backed {@link RemoteConfig.ConfigBackend} -- reads a mounted JSON profile map. No network
 * calls, no environment-variable secret reads.
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
@Component
public class FileBackend implements RemoteConfig.ConfigBackend {

  private static final ObjectMapper MAPPER = new ObjectMapper();
  private static final String FILE_PATH_ENV_VAR = "REMOTE_CONFIG_FILE_PATH";

  private final Environment env;

  public FileBackend(Environment env) {
    this.env = env;
  }

  /**
   * Name the mounted file this backend reads, for a fail-closed lookup's error message. The path is
   * a mount location, not a credential.
   *
   * <p>Resolved with {@code getProperty} rather than {@code getRequiredProperty}: this runs on an
   * error path, so it must describe the source without throwing a second exception that would mask
   * the first. An unset property is itself the useful thing to report.
   */
  @Override
  public String describeSource() {
    String configuredPath = env.getProperty(FILE_PATH_ENV_VAR);
    if (configuredPath == null || configuredPath.isBlank()) {
      return "config file (unset: " + FILE_PATH_ENV_VAR + ")";
    }
    return "config file '" + configuredPath + "'";
  }

  @Override
  @SuppressWarnings("unchecked")
  public Map<String, Object> fetchProfile(String profile) {
    // Resolved lazily on every call (never at construction, never at
    // Spring context refresh) -- a connections-only service (RemoteConfig
    // is always-on, but its poll loop is never
    // auto-started for a connections-only service, matching python's own
    // parity) never touches REMOTE_CONFIG_FILE_PATH at all, since
    // fetchProfile is only reached via refresh()/start(), which nothing
    // calls automatically in that case.
    Path configFilePath = Path.of(env.getRequiredProperty(FILE_PATH_ENV_VAR));
    if (!Files.exists(configFilePath)) {
      return Map.of();
    }
    try {
      Map<String, Object> allProfiles =
          MAPPER.readValue(Files.readAllBytes(configFilePath), Map.class);
      return (Map<String, Object>) Optional.ofNullable(allProfiles.get(profile)).orElse(Map.of());
    } catch (IOException e) {
      throw new IllegalStateException(
          "Failed to read remote-config file at " + configFilePath + ": " + e.getMessage(), e);
    }
  }
}
